import React, { useState } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';

const NavTop = ({ role = "tenant" }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const [darkMode, setDarkMode] = useState(false);

  const toggleTheme = () => {
    setDarkMode(!darkMode);
    document.documentElement.classList.toggle('dark');
  };

  const linkClass = (path) => `font-label-md text-label-md font-medium transition-colors ${location.pathname === path ? 'text-primary dark:text-primary-fixed border-b-2 border-primary pb-1' : 'text-secondary dark:text-secondary-fixed-dim hover:text-primary'}`;

  return (
    <header className="fixed top-0 w-full z-50 bg-white/70 dark:bg-secondary/60 backdrop-blur-xl border-b border-white/20 dark:border-outline-variant/10 shadow-[0_20px_40px_rgba(0,0,0,0.05)] h-20">
      <div className="flex justify-between items-center h-full px-margin-mobile md:px-margin-desktop max-w-container-max mx-auto">
        <Link to="/" className="flex items-center gap-2 hover:scale-[1.02] transition-transform">
          <span className="text-2xl font-black text-primary dark:text-inverse-primary tracking-tight">RentEase</span>
        </Link>

        <nav className="hidden md:flex items-center gap-8">
          <Link to="/discovery" className={linkClass("/discovery")}>Discover</Link>
          <Link to={role === 'host' ? "/landlord" : "/tenant"} className={linkClass(role === 'host' ? "/landlord" : "/tenant")}>
            {role === 'host' ? "Manage" : "Bookings"}
          </Link>
          <Link to="/messages" className={linkClass("/messages")}>Messages</Link>
        </nav>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => navigate(role === "tenant" ? "/landlord" : "/tenant")}
            className="hidden lg:flex items-center px-5 py-2.5 rounded-full bg-primary/10 text-primary font-bold hover:bg-primary/20 transition-all text-sm"
          >
            Switch to {role === "tenant" ? "Host" : "Tenant"}
          </button>
          <button onClick={toggleTheme} className="p-2 rounded-full hover:bg-surface-container transition-colors">
            <span className="material-symbols-outlined">{darkMode ? 'light_mode' : 'dark_mode'}</span>
          </button>
          <div className="w-10 h-10 rounded-full bg-surface-container overflow-hidden border border-outline-variant hover:scale-[1.02] transition-transform cursor-pointer">
            <img src="https://lh3.googleusercontent.com/aida-public/AB6AXuDhUS5LsRz4vJXm8dXqoP56KLDKNLYq_R2uTta_iUf31SEvvHsr6ZD7B3DjlsWbwclOIabcBos0WS5Yz3CjbMhudQkLzHTUbDujCWq4z1Sl52T0m_OjThrJis_3DOkf2i5Wty_syIr2fykvDlDfJ6X1weye-6eTZ_zgFqSWnsq55Cixn80STAHpH4ij_E1EQCOHbbVB-HfJCmaL_TFpwfSjbPBOVkI7ag-7lvaf2Jjby_bcUwAOVPBRgc8qriE8k3Bn0TyU7yKX7mE" className="w-full h-full object-cover" alt="User Profile" />
          </div>
        </div>
      </div>
    </header>
  );
};

export default NavTop;
